-- Which version of the server generated the demo team.
--
-- A demo is regenerated whenever the running server is not the one that made
-- it. Upgrading a stand used to leave it with the previous version's team -
-- no pulses after v0.17, no calendar after v0.21, no notes after v0.25 - and
-- each time a startup step was added to patch in the one thing that was new
-- (ADR 0013). A generator the stand is born from again on every upgrade has
-- nothing to patch.
--
-- Null on a demo seeded before this column existed, and on every installation
-- that is not a demo: neither was generated by the running version.
ALTER TABLE settings ADD COLUMN demo_seeded_by text;
